# Reviewed non-reads. The audit (run-gates.sh --check) flags a gate script that names a mapped path. Each
# row below records a name that is a fixture built in a temp dir, a comment, or a test that only names a
# script it calls (a script-to-script edge is a map row above). Format: @noread<TAB>gate<TAB>map globs
# (space-separated, as written in the rows above). A row that no longer matches anything fails --check.
# Fixture READMEs and docs written into a temp dir:
@noread	bash scripts/check-doc-sync.test.sh	README.md EXAMPLES.md
@noread	bash scripts/check-docs.test.sh	README.md
@noread	bash scripts/day-one.test.sh	README.md
@noread	bash scripts/gate-ratchet.test.sh	README.md
@noread	bash scripts/seeded-gates.test.sh	README.md
@noread	bash scripts/seeded-change-size.test.sh	README.md
@noread	bash scripts/seeded-review-gate.test.sh	README.md
@noread	bash scripts/test-budget.test.sh	README.md
@noread	bash scripts/measure-seeded-load.sh	README.md
@noread	bash scripts/post-edit-lint.test.sh	README.md CHANGELOG.md
@noread	bash scripts/test-harness-kit.sh	README.md CHANGELOG.md
@noread	bash scripts/test-template-copy.sh	README.md FUTURE.md
@noread	bash scripts/lint-skills.test.sh	FUTURE.md
# A prose or hook-payload mention of a document, not a read:
@noread	bash scripts/test-ci-templates.sh	README.md
@noread	node adapters/opencode/hooks.test.mjs	README.md
# The test of the gate tooling builds its own adapters/ tree:
@noread	bash scripts/check-tests-wired.test.sh	adapters/*
@noread	bash scripts/migrate-baseline.test.sh	adapters/*
# Comments that name another script:
@noread	bash scripts/check-fences.sh	scripts/check-golden.sh scripts/check-fences-frozen.sh
@noread	bash scripts/check-fences.sh --from-templates	scripts/check-golden.sh scripts/check-fences-frozen.sh
@noread	bash scripts/check-golden.sh	scripts/test-template-copy.sh
@noread	bash scripts/check-golden.sh --from-templates	scripts/test-template-copy.sh
# The test of this script names the gates and paths it maps, by design, in fixtures and in the real-map checks:
@noread	bash scripts/run-gates.test.sh	*
# The changelog tools: fixture READMEs in scratch repos, the fragment dir's own README, and a comment that
# lists the version gates a release replays:
@noread	bash scripts/changelog-check.test.sh	README.md
@noread	bash scripts/changelog-assemble.test.sh	README.md
@noread	bash scripts/changelog-check.sh {BASE}	README.md scripts/check-golden.sh scripts/regen-golden.sh scripts/check-doc-sync.sh scripts/validate-manifest.sh scripts/check-versions.sh
